<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
airi_admin_require();$pdo=airi_db();
function e(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$stats=[
 'installs'=>(int)$pdo->query('SELECT COUNT(*) FROM installations')->fetchColumn(),
 'devices'=>(int)$pdo->query('SELECT COUNT(DISTINCT machine_hash) FROM installations')->fetchColumn(),
 'dau'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE last_seen>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)")->fetchColumn(),
 'mau'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE last_seen>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn(),
 'licensed'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE license_state='licensed'")->fetchColumn(),
 'trial'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE license_state='trial' AND last_seen>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn(),
 'verified'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE integrity_state='verified'")->fetchColumn(),
 'suspicious'=>(int)$pdo->query("SELECT COUNT(DISTINCT machine_hash) FROM installations WHERE risk_score>=50 OR integrity_state IN('mismatch','revoked_build')")->fetchColumn(),
];
$versions=$pdo->query("SELECT COALESCE(NULLIF(app_version,''),'unknown') version,COUNT(DISTINCT machine_hash) users,MAX(last_seen) last_seen FROM installations GROUP BY app_version ORDER BY users DESC LIMIT 20")->fetchAll();
$daily=$pdo->query("SELECT DATE(last_seen) d,COUNT(DISTINCT machine_hash) users FROM installations WHERE last_seen>=DATE_SUB(UTC_DATE(),INTERVAL 29 DAY) GROUP BY DATE(last_seen) ORDER BY d")->fetchAll();
$maxDaily=1;foreach($daily as $r)$maxDaily=max($maxDaily,(int)$r['users']);
$licenseMix=$pdo->query("SELECT license_state,COUNT(DISTINCT machine_hash) users FROM installations GROUP BY license_state ORDER BY users DESC")->fetchAll();
$integrity=$pdo->query("SELECT integrity_state,COUNT(DISTINCT machine_hash) users FROM installations GROUP BY integrity_state ORDER BY users DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIRI User Analytics</title><style>
:root{--cream:#fff8ea;--white:#fff;--blue:#0f4c81;--sky:#58a6ff;--navy:#17283f;--muted:#607086;--line:#dce6f0;--green:#17643a;--red:#a12a2a}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--navy);font:14px Segoe UI,system-ui,sans-serif}.wrap{max-width:1300px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px}a{color:var(--blue);text-decoration:none}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:20px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;box-shadow:0 5px 18px #17283f0b}.stat span{color:var(--muted)}.stat b{display:block;font-size:27px;margin-top:6px}.cols{display:grid;grid-template-columns:1.5fr 1fr;gap:14px;margin-top:14px}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left}.bars{display:flex;align-items:flex-end;height:190px;gap:4px;padding-top:18px;border-bottom:1px solid var(--line)}.bar{flex:1;min-width:5px;background:linear-gradient(#58a6ff,#0f4c81);border-radius:5px 5px 0 0;position:relative}.bar:hover:after{content:attr(data-tip);position:absolute;bottom:100%;left:50%;transform:translateX(-50%);white-space:nowrap;background:#17283f;color:#fff;padding:5px 7px;border-radius:7px;font-size:11px;z-index:3}.pill{display:inline-block;padding:5px 8px;border-radius:999px;background:#edf5fc;color:var(--blue);font-weight:700}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><b style="color:#0f4c81;letter-spacing:.08em">AIRI TECHNOLOGY</b><h1 style="margin:4px 0">User Analytics</h1><div class="muted">Unique-device analytics · no browsing/download-history telemetry</div></div><div><a href="./?admin=dashboard">Dashboard</a> · <a href="releases.php">Official Builds</a></div></div><div class="grid"><?php foreach([['Total installs',$stats['installs']],['Unique devices',$stats['devices']],['Active 24h',$stats['dau']],['Monthly active',$stats['mau']],['Licensed devices',$stats['licensed']],['Active trials',$stats['trial']],['Verified binaries',$stats['verified']],['Suspicious devices',$stats['suspicious']]] as[$l,$v]):?><div class="card stat"><span><?=e($l)?></span><b><?=number_format($v)?></b></div><?php endforeach?></div><div class="card" style="margin-top:14px"><h2 style="margin-top:0">30-day active-device trend</h2><div class="bars"><?php foreach($daily as$r):$h=max(3,(int)round(((int)$r['users']/$maxDaily)*100));?><div class="bar" style="height:<?=$h?>%" data-tip="<?=e((string)$r['d'])?> · <?=(int)$r['users']?> devices"></div><?php endforeach?></div></div><div class="cols"><div class="card"><h2 style="margin-top:0">Version adoption</h2><table><thead><tr><th>Version</th><th>Unique devices</th><th>Last seen</th></tr></thead><tbody><?php foreach($versions as$r):?><tr><td><span class="pill"><?=e((string)$r['version'])?></span></td><td><b><?=(int)$r['users']?></b></td><td class="muted"><?=e((string)$r['last_seen'])?></td></tr><?php endforeach?></tbody></table></div><div><div class="card"><h2 style="margin-top:0">License mix</h2><table><?php foreach($licenseMix as$r):?><tr><td><?=e((string)$r['license_state'])?></td><td><b><?=(int)$r['users']?></b></td></tr><?php endforeach?></table></div><div class="card" style="margin-top:14px"><h2 style="margin-top:0">Binary integrity</h2><table><?php foreach($integrity as$r):?><tr><td><?=e((string)$r['integrity_state'])?></td><td><b><?=(int)$r['users']?></b></td></tr><?php endforeach?></table></div></div></div></div></body></html>
